                        height: '24px',
                        background: !isMuted ? '#28a745' : '#6c757d',
                        borderRadius: '12px',
                        cursor: 'pointer',
                        position: 'relative',
                        transition: 'background-color 0.3s ease',
                        border: '2px solid #fff',
                        boxShadow: '0 2px 4px rgba(0,0,0,0.2)'
                      }}
                    >
                      <div style={{
                        width: '18px',
                        height: '18px',
                        background: '#fff',
                        borderRadius: '50%',
                        position: 'absolute',
                        top: '1px',
                        left: !isMuted ? '27px' : '1px',
                        transition: 'left 0.3s ease',
                        boxShadow: '0 1px 3px rgba(0,0,0,0.3)'
                      }} />
                    </div>
                  </div>
                </>
              )}
            </div>

            {/* Content sections - only show if there's space */}
            {visibleSections.showSafeZone && (
              <div style={{ 
                padding: '0.75rem',
                background: 'rgba(255, 193, 7, 0.2)',
                borderRadius: '6px',
                border: '1px solid rgba(255, 193, 7, 0.4)',
                fontSize: '0.8rem',
                color: '#FFE066',
                flexShrink: 0
              }}>
                <div style={{ 
                  display: 'flex', 
                  alignItems: 'center', 
                  justifyContent: 'space-between',
                  marginBottom: safeZoneExpanded ? '0.25rem' : '0'
                }}>
                  <div style={{ fontWeight: 'bold', fontSize: '0.9rem', color: '#fff' }}>
                    🛡️ Safe Interaction Zone
                  </div>
                  <button
                    onClick={() => setSafeZoneExpanded(!safeZoneExpanded)}
                    style={{
                      background: 'none',
                      border: 'none',
                      fontSize: '1rem',
                      cursor: 'pointer',
                      color: '#fff',
                      padding: '0.25rem',
                      borderRadius: '4px',
                      transition: 'background-color 0.2s'
                    }}
                    onMouseEnter={(e) => {
                      e.currentTarget.style.backgroundColor = 'rgba(255, 255, 255, 0.1)';
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.backgroundColor = 'transparent';
                    }}
                    title={safeZoneExpanded ? 'Collapse Safe Zone' : 'Expand Safe Zone'}
                  >
                    {safeZoneExpanded ? '▼' : '▶'}
                  </button>
                </div>
                {safeZoneExpanded && (
                  <div style={{ lineHeight: '1.4', color: '#fff3cd', fontSize: '0.85em' }}>
                    You can safely interact with all buttons and elements in this simulation. This is an educational tool designed to show you how real scareware works. In real life, never click on security warning popups or enter information on suspicious pages.
                  </div>
                )}
              </div>
            )}

            {/* Speech explanation (shown when speech is enabled) */}
            {!isMuted && visibleSections.showSpeech && (
              <div style={{ 
                padding: '0.75rem',
                background: 'rgba(40, 167, 69, 0.2)',
                borderRadius: '6px',
                border: '1px solid rgba(40, 167, 69, 0.4)',
                fontSize: '0.8rem',
                color: '#90EE90',
                flexShrink: 0
              }}>
                <div style={{ 
                  display: 'flex', 
                  alignItems: 'center', 
                  justifyContent: 'space-between',
                  marginBottom: speechExpanded ? '0.25rem' : '0'
                }}>
                  <div style={{ fontWeight: 'bold', fontSize: '0.9rem', color: '#fff' }}>
                    🔊 Speech Mode Active
                  </div>
                  <button
                    onClick={() => setSpeechExpanded(!speechExpanded)}
                    style={{
                      background: 'none',
                      border: 'none',
                      fontSize: '1rem',
                      cursor: 'pointer',
                      color: '#fff',
                      padding: '0.25rem',
                      borderRadius: '4px',
                      transition: 'background-color 0.2s'
                    }}
                    onMouseEnter={(e) => {
                      e.currentTarget.style.backgroundColor = 'rgba(255, 255, 255, 0.1)';
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.backgroundColor = 'transparent';
                    }}
                    title={speechExpanded ? 'Collapse Speech Info' : 'Expand Speech Info'}
                  >
                    {speechExpanded ? '▼' : '▶'}
                  </button>
                </div>
                {speechExpanded && (
                  <div style={{ lineHeight: '1.4', color: '#e6ffe6', fontSize: '0.85em' }}>
                    The scareware will now speak its threats and demands out loud, simulating how real scareware might use audio to create urgency and pressure. This helps demonstrate the psychological manipulation tactics used by actual malware.
                  </div>
                )}
              </div>
            )}

            {/* Current Scareware Goal */}
            {visibleSections.showGoal && (
              <div style={{ 
                padding: '0.75rem',
                background: 'rgba(0, 123, 255, 0.2)',
                borderRadius: '6px',
                border: '1px solid rgba(0, 123, 255, 0.4)',
                fontSize: '0.8rem',
                color: '#66b3ff',
                flexShrink: 0
              }}>
                <div style={{ 
                  display: 'flex', 
                  alignItems: 'center', 
                  justifyContent: 'space-between',
                  marginBottom: goalExpanded ? '0.25rem' : '0'
                }}>
                  <div style={{ fontWeight: 'bold', fontSize: '0.95rem', color: '#fff' }}>
                    Current Scareware Goal
                  </div>
                  <button
                    onClick={() => setGoalExpanded(!goalExpanded)}
                    style={{
                      background: 'none',
                      border: 'none',
                      fontSize: '1rem',
                      cursor: 'pointer',
                      color: '#fff',
                      padding: '0.25rem',
                      borderRadius: '4px',
                      transition: 'background-color 0.2s'
                    }}
                    onMouseEnter={(e) => {
                      e.currentTarget.style.backgroundColor = 'rgba(255, 255, 255, 0.1)';
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.backgroundColor = 'transparent';
                    }}
                    title={goalExpanded ? 'Collapse Goal' : 'Expand Goal'}
                  >
                    {goalExpanded ? '▼' : '▶'}
                  </button>
                </div>
                {goalExpanded && (
                  <>
                    <div style={{ fontSize: '0.85rem', color: '#b0c4d6', fontWeight: 600, marginBottom: '0.4rem', marginTop: '0.1rem' }}>
                      {getScarewareGoal().label}
                    </div>
                    <div style={{ lineHeight: '1.5', color: '#e6f2ff', fontSize: '0.95em' }}>
                      {getScarewareGoal().description}
                    </div>
                  </>
                )}
              </div>
            )}
          </div>
        )}

        {/* Resize handle */}
        {!collapsed && (
          <div
            style={{
              position: 'absolute',
              bottom: '0',
              left: '0',
              right: '0',
              height: '6px',
              cursor: 'ns-resize',
              background: 'linear-gradient(to bottom, transparent, rgba(0, 123, 255, 0.3))',
              borderBottomLeftRadius: '9px',
              borderBottomRightRadius: '9px',
              zIndex: 100000
            }}
            onMouseDown={handleResizeMouseDown}
            onTouchStart={handleResizeMouseDown}
            title="Drag to resize"
          />
        )}
      </div>
    </>
  );
};

export default SimulationControls;
